insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('dc5d2c3e-06dc-49c8-b68a-f895b446d1a5', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$inleiding: zorgkosten groeien sneller dan het bbp; prognose 2040$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context1.png$$,
   $$In een land rapporteert een onderzoeksbureau in 2016 over de toenemende kosten van de zorg. Het bureau voorziet een groei van de zorgkosten die aanzienlijk hoger is dan de groei van het bruto binnenlands product (bbp):
− De zorgkosten, die in 2016 9% van het bbp bedragen, zullen met 3,5% per jaar stijgen bij een jaarlijkse groei van het bbp van 1,32%.
− Hieruit valt te berekenen dat de zorgkosten zullen oplopen tot meer dan 14% van het bbp in 2040.
− Voor mensen die ouder zijn dan de pensioengerechtigde leeftijd van zeventig jaar zijn de zorgkosten per persoon in 2016 gemiddeld ruim drie keer zo hoog als van mensen onder die leeftijd. Deze verhouding zal de komende decennia nog verder toenemen. Verder constateert het bureau dat vanaf een leeftijd van rond zeventig jaar mensen sowieso gemiddeld te maken krijgen met hogere zorgkosten.$$, 'inline'),
  ('bc5fbdd4-2673-4c0c-a020-a0555467a8fb', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$journaliste vat systeem van zorgfinanciering samen$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context2.png$$,
   $$Voor een artikel over de gezondheidszorg bestudeert een journaliste het rapport. Ze vat het systeem van de zorg en de wijze waarop dit is gefinancierd schematisch samen zoals weergegeven in figuur 1.$$, 'inline'),
  ('c406d975-19f4-464a-beec-c57af15c3ffb', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$figuur 1: systeem van financiering van de zorg$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context3.png$$,
   $$Figuur 1 Systeem van financiering van de zorg
Schema met drie partijen: verzekerden betalen premies aan verzekeraars; verzekeraars betalen vergoedingen aan zorgaanbieders; zorgaanbieders leveren zorg aan verzekerden.$$, 'inline'),
  ('cbf07c70-2bd9-4ef5-aea8-b451e6b5e3e5', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$nettozorgprofijt; verplichte solidariteit jong-oud bij uniforme premie$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context4.png$$,
   $$De journaliste introduceert het begrip nettozorgprofijt met als definitie: kosten van genoten zorg − betaalde bijdragen aan de zorg. Zij stelt dat het handhaven van een systeem met een uniforme premie neerkomt op verplichte solidariteit van relatief jonge verzekerden ten opzichte van oudere. Als de zorgkosten blijven stijgen zal deze verplichting zwaarder worden en kan dit leiden tot onvrede bij jongere verzekerden. De journaliste wijst er op dat het systeem voor hen op termijn ook voordelig kan zijn. Zij verwacht dat de jongere verzekerden van nu, gezien de aanhoudende stijging van de zorgkosten, over hun hele levensloop toch nog een positief nettozorgprofijt kunnen verwachten.$$, 'inline'),
  ('e4cc7d2c-ad5e-4fbd-a381-87d53bf7b943', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$twee verzekeringen: jongeren en ouderen; financiële planning over de levensloop$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context5.png$$,
   $$Een manier om rekening te houden met verschillen tussen generaties is het instellen van twee verzekeringen: één voor mensen jonger dan de pensioengerechtigde leeftijd, en één voor ouderen, die dan gemiddeld hogere premies betalen. Dan wordt minder beroep gedaan op de solidariteit tussen de generaties, wat de onvrede bij de jongere verzekerden ten aanzien van de zorgverzekering zou kunnen verminderen. De journaliste stelt dat verzekerden uit deze groep bij de financiële planning over hun levensloop dan wel rekening dienen te houden met de vraag wat het bestaan van twee verschillende verzekeringen voor hen betekent wanneer zij zelf eens de pensioengerechtigde leeftijd zullen hebben bereikt.$$, 'inline'),
  ('abe1a665-4f37-4f1d-98fc-52a9d3c0eadb', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$nieuw zorgsysteem: verplicht basispakket met vast eigen risico, vrije premie$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context6.png$$,
   $$Volgens het rapport kan de verwachte stijging van de zorgkosten worden aangepakt met een nieuw zorgsysteem waarbij de overheid een basispakket gezondheidszorg verplicht stelt met een vast eigen risico. Mensen kunnen in dat systeem zelf kiezen bij welke verzekeraar zij zich willen verzekeren. Verzekeraars mogen niemand weigeren, maar mogen wel zelf de hoogte van hun premie vaststellen. Volgens het rapport kan dit systeem via de marktrelaties tussen verzekerden, verzekeraars en zorgaanbieders, zoals weergegeven in figuur 1, een matigende invloed hebben op de stijging van de zorgkosten.$$, 'inline'),
  ('f64a3e1e-a6b6-4912-85c1-f3f4c099de78', '3b82b63c-3cb7-485a-b548-60ceaf897b28', $$journaliste: eigen risico kan denivellerend werken$$,
   $$economie-vwo-2018-ii-hoe-verdelen-we-de-zorgkosten-context7.png$$,
   $$De journaliste voorziet echter een effect waaraan in het rapport geen aandacht is geschonken: “Een systeem met een eigen risico kan leiden tot denivellering van de beschikbare inkomens van gezinshuishoudingen na aftrek van betaalde bijdragen aan de zorg.”$$, 'inline'),
  ('47bcf3da-04c1-4a84-b518-b6590503bff0', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$inleiding: arbeidsproductiviteit, loonkosten en arbeidsmarkt 2003-2014$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context1.png$$,
   $$In een land publiceert een onderzoeksbureau gegevens over de gemiddelde arbeidsproductiviteit, de beloning van arbeid en de situatie op de arbeidsmarkt in de periode 2003-2014 (figuur 1 en tabellen 1 en 2). Als veroorzakende factoren voor de verandering van de arbeidsproductiviteit wordt alleen gekeken naar de ontwikkeling van de informatie- en communicatietechnologie (ICT) en van de scholing van de beroepsbevolking. Andere factoren blijven hier onbenoemd. Het bureau stelt: “In de periode van 2009-2013 heeft de stijging van de arbeidsproductiviteit niet geleid tot hogere reële loonkosten per uur.” Een econoom concludeert op basis van de figuur dat de reële loonkosten per eenheid product zijn gedaald, waardoor de winstgevendheid van bedrijven moet zijn gestegen.$$, 'inline'),
  ('0f66547d-2ef7-4c98-be73-5db666157798', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$figuur 1: arbeidsproductiviteit en reële loonkosten per uur (indexcijfers, 2003 = 100)$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context2.png$$,
   $$Figuur 1 Arbeidsproductiviteit en loonkosten, ontwikkelingen 2003-2014 (indexcijfers, 2003 = 100)
arbeidsproductiviteit per uur: 2003 100; 2004 102,1; 2005 104,9; 2006 106,7; 2007 108,1; 2008 108,7; 2009 105,9; 2010 108,6; 2011 109,6; 2012 109,3; 2013 109,6; 2014 110,4
reële loonkosten per uur: 2003 100; 2004 101,8; 2005 101,1; 2006 101,5; 2007 103,2; 2008 104,4; 2009 105,0; 2010 103,9; 2011 103,8; 2012 103,6; 2013 103,3; 2014 104,5$$, 'inline'),
  ('c980a4c8-4576-430c-90eb-2bdb2984dc06', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$tabel 1: verandering arbeidsproductiviteit per verklarende factor (ICT, scholing)$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context3.png$$,
   $$Tabel 1 veranderig arbeidsproductiviteit (%) per verklarende factor¹⁾
| 2003-2008²⁾ | 2009 | 2010-2014²⁾
ICT | +1,26 | +0,27 | +1,00
scholing van de beroepsbevolking | +3,03 | +0,80 | +2,53
¹⁾ Percentages, toe te rekenen aan de genoemde factoren. Andere factoren die de arbeidsproductiviteit bepalen, blijven onbenoemd.
²⁾ De percentages gelden voor het geheel van de periode, niet per jaar.$$, 'inline'),
  ('37adb704-d10e-4d69-b735-a5a8e0e7cf73', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$tabel 2: jaarlijkse verandering van het aantal gewerkte uren$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context4.png$$,
   $$Tabel 2 jaarlijkse verandering van het aantal gewerkte uren (%)
| 2003-2008 | 2009 | 2010-2014
jaarlijkse verandering gewerkte uren | + 0,7 | -1,4 | -0,2$$, 'inline'),
  ('769a8f52-9ffc-4605-bed2-2b4d4693a1cd', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$2009: ontslagen; gewerkte uren minder sterk gedaald dan productie$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context5.png$$,
   $$In 2009 hebben werkgevers veel mensen ontslagen, met als gevolg een toename van de werkloosheid. De econoom concludeert op basis van figuur 1 en tabel 2: “Het totale aantal gewerkte uren is in 2009 toch minder sterk gedaald dan de productie.”$$, 'inline'),
  ('ba7f28cb-f2ff-45a4-8ad6-af91043f14f1', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', $$scholing als oorzaak van niet-stijgende arbeidsbeloning 2009-2013$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-context6.png$$,
   $$Een verbeterd scholingsniveau van werkenden kan voor werkgevers aanleiding zijn geweest om veranderingen door te voeren in de inzet van kapitaal en arbeid, met als gevolg een daling van de werkgelegenheid. De econoom veronderstelt daarom dat in de periode 2009-2013 scholing van de beroepsbevolking juist een oorzaak kan zijn geweest dat de arbeidsbeloning per uur niet is gestegen.$$, 'inline'),
  ('3ebd14e4-e879-4e42-a719-b7e219061b6b', 'a790e93a-0d93-4206-b418-cde50f649edb', $$inleiding: neergaande conjunctuur in Mantano, toch meer eigen huizen$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context1.png$$,
   $$Het land Mantano kende in 2015 en 2016 een neergaande conjunctuur. Opmerkelijk is dat desondanks steeds meer mensen een eigen huis bleken te kopen, gefinancierd met een hypothecaire lening. De regering vraagt aan econoom Ron Estate om te onderzoeken of dit mogelijk procyclisch kan uitwerken. Estate verzamelt gegevens over de huizenmarkt en de hypothecaire leningen in Mantano en presenteert de onderstaande tabellen.$$, 'inline'),
  ('9376f8af-98c4-4f65-abe6-647f9bad16e3', 'a790e93a-0d93-4206-b418-cde50f649edb', $$tabel 1: verdeling eigen huizen en huurhuizen in Mantano$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context2.png$$,
   $$Tabel 1 verdeling eigen huizen en huurhuizen in het land Mantano
jaar (per 31 december) | 2004 | 2009 | 2014 | 2016
aantal woonhuizen | 5.400.000 | 5.700.000 | 5.925.000 | 6.000.000
% eigen huizen | 35 | 40 | 42 | 44
% huurhuizen | 65 | 60 | 58 | 56$$, 'inline'),
  ('dffcc8e9-9795-4bc9-af08-f680cdd787f5', 'a790e93a-0d93-4206-b418-cde50f649edb', $$tabel 2: gebruik van hypothecaire lening bij aankoop eigen huis$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context3.png$$,
   $$Tabel 2 gebruik van hypothecaire lening bij aankoop eigen huis
jaar (per 31 december) | 2004 | 2009 | 2014 | 2016
percentage bezitters van een eigen huis met een uitstaande hypothecaire lening | 70 | 81 | 90 | 92$$, 'inline'),
  ('e84bf31b-075e-4744-bffb-375ea2093b54', 'a790e93a-0d93-4206-b418-cde50f649edb', $$tabel 3: omvang hypothecaire lening en aankoopprijs eigen huis$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context4.png$$,
   $$Tabel 3 omvang van hypothecaire lening en aankoopprijs van een eigen huis (gemiddelden omgerekend in euro’s)
jaar (per 31 december) | 2004 | 2009 | 2014 | 2016
omvang hypothecaire lening | 110.000 | 130.000 | 169.000 | 190.000
aankoopprijs eigen huis | 150.000 | 165.000 | 180.000 | 200.000$$, 'inline'),
  ('967aff71-f779-4248-8af2-dbbe508fba75', 'a790e93a-0d93-4206-b418-cde50f649edb', $$bevindingen a t/m d van Estate$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context5.png$$,
   $$Estate komt tot de volgende bevindingen:
a In een neergaande conjunctuur daalt gewoonlijk het percentage ‘eigen huizen’ binnen het totale aantal woonhuizen.
b Mogelijk veroorzaakte de neergaande conjunctuur een verandering op de vermogensmarkt waardoor het percentage ‘eigen huizen’ per saldo toch steeg.
c De totale hypothecaire schuld van bezitters van een eigen huis was aan het eind van 2016 hoger dan het bruto binnenlands product (bbp), dat in datzelfde jaar € 450 miljard bedroeg.
d Een te grote verhouding tussen de totale hypothecaire leenschuld van eigen huizenbezitters en het bbp kan procyclisch uitwerken.$$, 'inline'),
  ('4db27166-800d-4336-8d0e-3d8c0795301b', 'a790e93a-0d93-4206-b418-cde50f649edb', $$Estate: huizenbezitters minder bezorgd over financiële risico's (tabel 3)$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context6.png$$,
   $$Estate ziet in tabel 3 een aanwijzing dat huizenbezitters met een hypotheekschuld in de periode 2004-2016 zich minder zorgen zijn gaan maken om financiële risico’s.$$, 'inline'),
  ('1300e82a-435a-4f14-992a-f0f581dd3bb0', 'a790e93a-0d93-4206-b418-cde50f649edb', $$advies: maximum aan hypotheekrenteaftrek$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-context7.png$$,
   $$In Mantano kunnen huizenbezitters de door hen betaalde hypotheekrente volledig aftrekken voor de bepaling van hun belastbaar inkomen. Op basis van zijn eerdere bevindingen adviseert Estate de regering om (potentiële) huizenkopers minder gebruik te laten maken van hypothecair krediet door aan de hypotheekrenteaftrek een maximum te stellen van omgerekend tienduizend euro per jaar.$$, 'inline'),
  ('35a2b6da-ce55-4861-bcb7-7198803b3f98', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$inleiding: muntunie vergroot volgens Stiglitz de ongelijkheid tussen landen$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context1.png$$,
   $$In 2016 ontstaat er discussie over de gevolgen van de muntunie voor de landen van de eurozone. De Economische en Monetaire Unie (EMU) is opgericht in de verwachting dat een gemeenschappelijke munt zou leiden tot verkleining van de verschillen in groeitempo van de deelnemende economieën. De econoom Joseph Stiglitz stelt daarentegen dat de muntunie en de afspraken binnen de EMU juist leiden tot vergroting van de ongelijkheid tussen de landen. Figuur 1 laat zien dat in de periode 2007-2015 het reële bruto binnenlands product (bbp) in Nederland en Duitsland (‘het Noorden’) is gegroeid, en in Griekenland, Portugal en Spanje (‘het Zuiden’) is gedaald.$$, 'inline'),
  ('3706e791-25bd-4798-b18d-05506c6b2208', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$figuur 1: cumulatieve procentuele groei reële bbp 2007-2015$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context2.png$$,
   $$Figuur 1 cumulatieve procentuele groei reële bbp, 2007-2015
Staafdiagram: Duitsland 6,5; Nederland 5; Spanje −3; Griekenland −25,5; Portugal −6,5$$, 'inline'),
  ('2ba3f517-16dc-4a75-8329-0df28d01abc4', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$journalist: aanpassingsmechanismen niet meer beschikbaar na invoering euro$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context3.png$$,
   $$Een journalist vat de analyse van Stiglitz samen: Voor de invoering van de euro kende het Zuiden gemiddeld genomen een lagere groei van de arbeidsproductiviteit dan het Noorden, met als gevolg een verslechtering van de concurrentiepositie van het Zuiden. Dit effect kon op korte termijn worden verminderd door een aantal aanpassingsmechanismen. Na invoering van de euro zijn deze niet meer beschikbaar:
− Er is geen onderlinge wisselkoers meer, zodat aanpassing van de wisselkoers niet meer mogelijk is.
− Door het gezamenlijk rentebeleid is het voor landen niet meer mogelijk om een eigen rentebeleid te voeren.
− Door het Groei- en Stabiliteitspact is het nog maar beperkt mogelijk om begrotingsbeleid te voeren.$$, 'inline'),
  ('c9051fee-bf63-4cd0-8496-c42a8f79f235', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$aanpassing via de arbeidsmarkt is langdurig en pijnlijk$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context4.png$$,
   $$Na invoering van de euro moet aanpassing bij achterblijvende groei van de arbeidsproductiviteit plaatsvinden door een aanpassingsproces op de arbeidsmarkt die de internationale concurrentiepositie doet verbeteren. Dat is echter een langdurig en pijnlijk proces, dat tot maatschappelijke onrust kan leiden.$$, 'inline'),
  ('6a7e6ce9-c869-42e4-a1e0-0e97264e72ad', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$Groei- en Stabiliteitspact en rentebeleid ECB$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context5.png$$,
   $$De journalist licht verder toe:
− Het Groei- en Stabiliteitspact houdt in dat de speelruimte voor het begrotingsbeleid van de lidstaten wordt beperkt doordat het overheidstekort maximaal 3% van het bbp mag bedragen. Dat betekent dat landen met een krimpend bbp nauwelijks maatregelen kunnen nemen om de ontwikkeling van de conjunctuur of van de structuur te stimuleren.
− Lidstaten hebben hun rentebeleid uit handen gegeven aan de Europese Centrale Bank (ECB). De ECB moet daarbij rekening houden met een belangentegenstelling tussen lidstaten met een sterke groei van het bbp en lidstaten die te maken hebben met een krimpend reëel bbp.$$, 'inline'),
  ('f7ec0204-2bf3-4217-bfb8-6ff4e424c291', '18680923-0e04-4ff2-8cb2-e3cd482c58f2', $$arbeidsmigratie van hoger opgeleiden$$,
   $$economie-vwo-2018-ii-armer-door-muntunie-context6.png$$,
   $$In landen waar de economische groei langdurig laag blijft omdat op korte termijn aanpassingsmechanismen niet of onvoldoende werkzaam zijn, zal arbeidsmigratie optreden, vooral van hoger opgeleiden. Stiglitz waarschuwt dat dit kan leiden tot een verder uiteenlopen van de economische ontwikkeling tussen lidstaten binnen de Eurozone.$$, 'inline'),
  ('7b29778e-69de-4436-bee7-9f563dbbd702', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$inleiding: CO₂-heffing; overheid heeft informatieachterstand$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context1.png$$,
   $$De overheid van een groot industrieland wil bedrijven er toe aanzetten om over te stappen naar productietechnieken met minder uitstoot (emissie) van kooldioxide (CO₂). Om dit doel te bereiken is een heffing van kracht op deze emissie. Een econoom meent dat voor de overheid het bepalen van de juiste hoogte van de heffing voor de gewenste reductie van de emissie wordt bemoeilijkt, doordat zij een informatieachterstand heeft ten opzichte van bedrijven ten aanzien van hun kostenstructuur.$$, 'inline'),
  ('5f0c32f0-63fc-40da-a76a-582c87c42e22', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$systeem van emissierechten met dalend emissieplafond$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context2.png$$,
   $$Als alternatief heeft de overheid een systeem ingesteld waarbij zij elk jaar emissierechten aanbiedt. Elk emissierecht geeft aan een bedrijf het recht om gedurende een jaar één ton CO₂ uit te stoten. Bedrijven kunnen bieden op deze emissierechten, en kunnen deze opsparen voor een later jaar. Zij kunnen ook eerder uitgegeven emissierechten kopen van andere bedrijven. Bedrijven die meer CO₂ uitstoten dan hun rechten toelaten, worden zwaar beboet. De overheid wil het aanbod van nieuwe emissierechten (emissieplafond) jaarlijks met 1,7% verlagen ten opzichte van het voorgaande jaar. Een econoom signaleert enkele factoren die het verloop van de prijs bepalen en schetst de verbanden in figuur 1. Figuur 2 toont het verloop van de prijs van een emissierecht omgerekend in euro’s.$$, 'inline'),
  ('afae5c9d-f7f3-4710-bc36-108bd02c2a99', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$figuur 1: prijs van een emissierecht, bepalende factoren en gevolgen; figuur 2: prijsverloop emissierecht$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context3.png$$,
   $$Figuur 1 prijs van een emissierecht; bepalende factoren en gevolgen
Schema: ''conjunctuur'', ''aanbod/emissieplafond'' en (via pijl A) ''kosten van uitstootloze energieopwekking'' wijzen naar ''prijs van een emissierecht''; van ''prijs van een emissierecht'' loopt een gestippelde pijl B naar ''investeringen in uitstootbesparende technieken''.
Figuur 2 prijs van een emissierecht in euro per ton CO₂-uitstoot
Grafiek van september 2014 tot eind 2016 (as 3,00-7,00 euro): prijs schommelt rond 6 euro (eind 2014), stijgt in 2015 tot ruim boven 7 euro (piek rond januari 2016), daalt begin 2016 sterk tot rond 5 euro en eindigt 2016 rond 4 euro.$$, 'inline'),
  ('289f4beb-ea9e-483e-92ec-f0c9fe0690e1', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$veronderstelling: prijs in 2015 beïnvloed door conjuncturele opgang$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context4.png$$,
   $$De econoom veronderstelt dat de prijs van een emissierecht in 2015 sterk was beïnvloed door de conjuncturele opgang in dat jaar.$$, 'inline'),
  ('c524de4c-13d6-4902-b127-93d80a583bac', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$politicus: afname emissieplafond in 2016 te bescheiden$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context5.png$$,
   $$Een politicus beweert op basis van figuur 2 dat de afname van het emissieplafond door de overheid in 2016 te bescheiden is geweest. Met een lager emissieplafond was er een nog groter effect geweest op de vermindering van de uitstoot van CO₂.$$, 'inline'),
  ('4c8e4d36-45a1-4201-bf70-b2da4ee4544b', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$econoom: bij pijl B telt de verwachte prijs$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context6.png$$,
   $$De econoom stelt dat ondernemingen bij pijl B meer kijken naar de verwachte prijsontwikkeling van een emissierecht dan naar de huidige prijs.$$, 'inline'),
  ('49fe047f-261d-41aa-beca-834dc5e40337', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$voorstel: fonds dat emissierechten opkoopt bij laagconjunctuur$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context7.png$$,
   $$Op grond van zijn veronderstelling dat de conjunctuur van invloed is op de prijs van emissierechten, adviseert de econoom de overheid om een fonds op te richten, dat emissierechten bij laagconjunctuur opkoopt. Na een conjunctureel herstel kan het fonds deze emissierechten weer op de markt aanbieden. Het saldo van het fonds wordt in zijn voorstel verrekend met de schatkist.$$, 'inline'),
  ('d1d2928d-d47a-4be0-9145-8e661ec82de6', '04e59747-0df9-4119-93ec-8a815a28bf0e', $$voorbeeld: keuze tussen bestaande en alternatieve productiewijze (tabel)$$,
   $$economie-vwo-2018-ii-inperken-van-de-uitstoot-context8.png$$,
   $$De econoom illustreert het effect van de prijs van een emissierecht op de keuze van productietechnieken met een voorbeeld. Een onderneming produceert 400.000 producten. De verwachting is dat deze productie niet zal veranderen. De onderneming kan kiezen uit twee productiewijzen:
| productiewijze in 2016 (bestaand) | alternatieve productiewijze
constante kosten in euro’s | 1,2 mln. | 1,6 mln.
variabele kosten in euro’s per product (exclusief kosten van emissierechten) | 0,6 | 0,7
emissie van CO₂ per product | 0,1 ton | 0,02 ton$$, 'inline');

