   '["arbeidsproductiviteit", "gewerkte uren", "productie", "laagconjunctuur", "indexcijfers"]'::jsonb,
   $$Uit productiviteits- en urencijfers afleiden dat de productie sterker daalde dan het aantal gewerkte uren.$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-vraag9.png$$, $$2p 9 Noem de gegevens uit figuur 1 en tabel 2 waarop de econoom zich baseert en leg uit hoe hij daarmee tot zijn conclusie is gekomen.$$, array['0f66547d-2ef7-4c98-be73-5db666157798', '37adb704-d10e-4d69-b735-a5a8e0e7cf73', '769a8f52-9ffc-4605-bed2-2b4d4693a1cd']::uuid[]),
  ('e9e54cc6-339f-4f5d-ace5-45bfa9a270f0', '6681d13e-b7cd-49e1-8ab4-fd26f1357f4c', 10,
