   '["labour hoarding", "verzonken kosten", "opleidingskosten", "ontslagkosten", "arbeidsvraag"]'::jsonb,
   $$Noemen van motieven om bij productiedaling relatief weinig personeel te ontslaan.$$,
   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-vraag10.png$$, $$2p 10 Noem twee motieven die werkgevers kunnen hebben gehad om de inzet van arbeid minder te verlagen dan de daling van de productie.$$, array['769a8f52-9ffc-4605-bed2-2b4d4693a1cd']::uuid[]),
