   $$economie-vwo-2018-ii-arbeidsproductiviteit-in-de-lift-vraag11.png$$, $$2p 11 Leg uit dat deze veronderstelling kan worden gebaseerd op gegevens in tabel 1.$$, array['c980a4c8-4576-430c-90eb-2bdb2984dc06', 'ba7f28cb-f2ff-45a4-8ad6-af91043f14f1']::uuid[]),
