   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-vraag12.png$$, $$2p 12 Leg bevinding b van Estate uit.$$, array['3ebd14e4-e879-4e42-a719-b7e219061b6b', '9376f8af-98c4-4f65-abe6-647f9bad16e3', 'dffcc8e9-9795-4bc9-af08-f680cdd787f5', 'e84bf31b-075e-4744-bffb-375ea2093b54', '967aff71-f779-4248-8af2-dbbe508fba75']::uuid[]),
