   '["hypotheekschuld berekenen", "schuld als percentage van het bbp", "voorraadgrootheid", "stroomgrootheid"]'::jsonb,
   $$Berekenen van de totale hypotheekschuld en vergelijken met het bbp.$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-vraag13.png$$, $$1p 13 Toon met een berekening aan dat bevinding c juist is.$$, array['9376f8af-98c4-4f65-abe6-647f9bad16e3', 'dffcc8e9-9795-4bc9-af08-f680cdd787f5', 'e84bf31b-075e-4744-bffb-375ea2093b54', '967aff71-f779-4248-8af2-dbbe508fba75']::uuid[]),
  ('9e78a836-c893-4f87-987f-05b966c75d9e', 'a790e93a-0d93-4206-b418-cde50f649edb', 14,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur"}, {"domain": "Ruilen over de tijd", "subdomain": "Intertemporele ruil"}]'::jsonb,
   '["procyclisch", "schuldenlast", "vermogenseffect", "consumptie", "conjuncturele neergang"]'::jsonb,
   $$Verklaren waarom een hoge hypotheekschuld een conjuncturele neergang versterkt.$$,
   $$economie-vwo-2018-ii-huizenmarkt-als-financiele-zeepbel-vraag14.png$$, $$2p 14 Verklaar waarom een te grote verhouding tussen de totale hypothecaire leenschuld van eigen huizenbezitters en het bbp in geval van een conjuncturele neergang procyclisch kan uitwerken.$$, array['967aff71-f779-4248-8af2-dbbe508fba75']::uuid[]),
  ('7e18921e-a55b-47e5-b8fc-1a134ebdaaa5', 'a790e93a-0d93-4206-b418-cde50f649edb', 15,
